function sessionCleanupFixture() {
 const calls:string[]=[];
 const ports:CurrentPushSessionCleanupPorts={
  session:vi.fn(async()=>{calls.push('session');return {userId:'current-user',sessionId:'current-session'};}),
  holdingId:vi.fn(async(slug)=>{calls.push('holding:'+slug);return 'h001';}),
  remove:vi.fn(async(holding,user,session)=>{calls.push(`remove:${holding}:${user}:${session}`);return {removed:true};}),
 };
 return {ports,calls,run:createCurrentPushSessionCleanup(ports)};
}
describe('Push cleanup authenticates its own session before selecting a business workspace',()=>{
 test.each([null,'https://unrelated.example'])('rejects origin %s before authentication or owner access',async origin=>{
  const f=sessionCleanupFixture();
  await expect(f.run({holdingSlug:'acme',origin,expectedOrigin:'https://console.example'})).rejects.toMatchObject({status:403,code:'ORIGIN_FORBIDDEN'});
  expect(f.calls).toEqual([]);
  expect(f.ports.session).not.toHaveBeenCalled();expect(f.ports.holdingId).not.toHaveBeenCalled();expect(f.ports.remove).not.toHaveBeenCalled();
 });
 test('a missing normal session returns 401 before Holding lookup or cleanup',async()=>{
  const f=sessionCleanupFixture();f.ports.session=vi.fn(async()=>null);
  await expect(f.run({holdingSlug:'acme',origin:'https://console.example',expectedOrigin:'https://console.example'})).rejects.toMatchObject({status:401,code:'UNAUTHENTICATED'});
  expect(f.ports.holdingId).not.toHaveBeenCalled();expect(f.ports.remove).not.toHaveBeenCalled();
 });
 test('unexpected authentication failures propagate without owner lookup or cleanup',async()=>{
  const f=sessionCleanupFixture(),failure=Error('authentication store unavailable');f.ports.session=vi.fn(async()=>{throw failure;});
  await expect(f.run({holdingSlug:'acme',origin:'https://console.example',expectedOrigin:'https://console.example'})).rejects.toBe(failure);
  expect(f.ports.holdingId).not.toHaveBeenCalled();expect(f.ports.remove).not.toHaveBeenCalled();
 });
 test('an unavailable Holding cannot invoke session cleanup',async()=>{
  const f=sessionCleanupFixture(),failure=Error('HOLDING_NOT_FOUND');f.ports.holdingId=vi.fn(async()=>{throw failure;});
  await expect(f.run({holdingSlug:'missing',origin:'https://console.example',expectedOrigin:'https://console.example'})).rejects.toBe(failure);
  expect(f.calls).toEqual(['session']);expect(f.ports.remove).not.toHaveBeenCalled();
 });
 test('uses only authenticated user and session IDs without Company selection',async()=>{
  const f=sessionCleanupFixture();
  await expect(f.run({holdingSlug:'acme',origin:'https://console.example',expectedOrigin:'https://console.example'})).resolves.toEqual({removed:true});
  expect(f.calls).toEqual(['session','holding:acme','remove:h001:current-user:current-session']);
  expect(f.ports.remove).toHaveBeenCalledExactlyOnceWith('h001','current-user','current-session');
 });
 test('does not turn a native cleanup failure into a successful response',async()=>{
  const f=sessionCleanupFixture(),failure=Error('subscription store unavailable');f.ports.remove=vi.fn(async()=>{throw failure;});
  await expect(f.run({holdingSlug:'acme',origin:'https://console.example',expectedOrigin:'https://console.example'})).rejects.toBe(failure);
 });
});
